rative": "A passenger car halts briefly in a bus_stop curb zone with its curb-side door open and moves off before the standing duration; no other road user is in the scene."}, {"name": "idle", "expected": "not_applicable", "narrative": "A bus halts in a bus_stop curb zone."}, {"name": "blind", "expected": "unknown", "narrative": "A passenger car halts briefly in a taxicab_stand curb zone and the source does not observe its doors.", "masked": ["sig.door_open"]}, {"name": "branch_1", "expected": "violated", "narrative": "A passenger car halts briefly in a bus_stop zone with a door open while a bus stands halted just outside the zone within the waiting reach."}, {"name": "branch_2", "expected": "violated", "narrative": "A truck halts briefly in a taxicab_stand zone with a door open: it is no passenger vehicle."}], "literals": [], "param_proposals": [{"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source (sensor or simulator specification)"}, {"name": "p.queue_halt_gap", "unit": "m", "value": 5.0, "convention": "the gap between bodies to a road user ahead in the same lane within which a halt is a halt behind other traffic: the spacing of halted vehicles in a queue", "source": "HCM queue spacing of stopped vehicles"}, {"name": "p.standing_min_duration", "unit": "s", "value": 60.0, "convention": "the longest halt counted as receiving or discharging passengers or loading rather than standing: a passenger pick-up dwell at the curb", "source": "curbside passenger pick-up dwell observations (ITE curbside management practice)"}, {"name": "p.zone_entry_wait_reach", "unit": "m", "value": 10.0, "convention": "the ground distance from a halted vehicle's body to a curb zone within which the vehicle counts as waiting to enter the zone: about one design passenger-car length plus the spacing of halted vehicles 