{"node_id": "NRS_484B_507_1", "law_refs": ["NRS-484B-507-1"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "s1", "text": "A person shall not stop, stand or park a vehicle", "role": "obligation"}, {"id": "s2", "text": "for any purpose or length of time", "role": "condition"}, {"id": "s3", "text": "other than for the expeditious", "role": "standard"}, {"id": "s4", "text": "unloading and delivery or pickup and loading of materials", "role": "exception"}, {"id": "s5", "text": "in any place marked as a freight curb loading zone", "role": "condition"}, {"id": "s6", "text": "during hours when the provisions applicable to such zones are in effect.", "role": "condition"}, {"id": "s7", "text": "The driver of a vehicle", "role": "exception"}, {"id": "s8", "text": "may stop temporarily", "role": "standard"}, {"id": "s9", "text": "at a place marked as a freight curb loading zone", "role": "exception"}, {"id": "s10", "text": "for the purpose of and while actually engaged in loading or unloading passengers,", "role": "exception"}, {"id": "s11", "text": "when such stopping does not interfere with", "role": "standard"}, {"id": "s12", "text": "any motor vehicle used for the transportation of materials", "role": "exception"}, {"id": "s13", "text": "which is waiting to enter or about to enter such zone.", "role": "exception"}], "elements": [{"span": "s1", "atoms": ["dev.governs", "dev.human_direction", "dev.railway_signal_or_gate", "dev.stop_sign", "dev.traffic_signal", "dev.yield_sign", "rel.ahead_behind_in_lane", "rel.occupies", "rel.surface_gap", "ru.aggregate=DEF-NRS-484A-320::vehicle", "st.travel_region"], "derived": ["drv.motion.complete_halt"], "justification": "'Stop' when prohibited is 'any halting, even momentarily, of a vehicle, whether occupied or not, except when necessary to avoid conflict with other traffic or in compliance with the directions of a police officer or official traffic-control device